import { useState } from 'react';
import { Link } from 'react-router-dom';
import axios from 'axios';

interface FormData {
  nome_solicitante: string;
  setor: string;
  titulo: string;
  local: string;
  descricao: string;
}

export default function SolicitacaoManutencao() {
  const [formData, setFormData] = useState<FormData>({
    nome_solicitante: '',
    setor: '',
    titulo: '',
    local: '',
    descricao: ''
  });

  const [enviando, setEnviando] = useState(false);
  const [mensagem, setMensagem] = useState<{ tipo: 'sucesso' | 'erro'; texto: string } | null>(null);

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    setEnviando(true);
    setMensagem(null);

    try {
      await axios.post('http://localhost:3001/api/solicitacoes', formData);
      setMensagem({
        tipo: 'sucesso',
        texto: 'Solicitação enviada com sucesso!'
      });
      setFormData({
        nome_solicitante: '',
        setor: '',
        titulo: '',
        local: '',
        descricao: ''
      });
    } catch (error) {
      setMensagem({
        tipo: 'erro',
        texto: 'Erro ao enviar solicitação. Tente novamente.'
      });
    } finally {
      setEnviando(false);
    }
  };

  const handleChange = (e: React.ChangeEvent<HTMLInputElement | HTMLTextAreaElement>) => {
    const { name, value } = e.target;
    setFormData(prev => ({ ...prev, [name]: value }));
  };

  return (
    <div className="min-h-screen bg-gray-50 py-12 px-4 sm:px-6 lg:px-8">
      <div className="max-w-md mx-auto">
        <div className="text-center">
          <h2 className="text-3xl font-extrabold text-gray-900">
            Solicitar Manutenção
          </h2>
          <p className="mt-2 text-sm text-gray-600">
            Preencha o formulário abaixo para solicitar um serviço de manutenção
          </p>
        </div>

        <form onSubmit={handleSubmit} className="mt-8 space-y-6">
          <div className="rounded-md shadow-sm -space-y-px">
            <div>
              <label htmlFor="nome_solicitante" className="sr-only">Nome do Solicitante</label>
              <input
                id="nome_solicitante"
                name="nome_solicitante"
                type="text"
                required
                value={formData.nome_solicitante}
                onChange={handleChange}
                className="appearance-none rounded-none relative block w-full px-3 py-2 border border-gray-300 placeholder-gray-500 text-gray-900 rounded-t-md focus:outline-none focus:ring-primary-500 focus:border-primary-500 focus:z-10 sm:text-sm"
                placeholder="Nome do Solicitante"
              />
            </div>
            <div>
              <label htmlFor="setor" className="sr-only">Setor</label>
              <input
                id="setor"
                name="setor"
                type="text"
                required
                value={formData.setor}
                onChange={handleChange}
                className="appearance-none rounded-none relative block w-full px-3 py-2 border border-gray-300 placeholder-gray-500 text-gray-900 focus:outline-none focus:ring-primary-500 focus:border-primary-500 focus:z-10 sm:text-sm"
                placeholder="Setor"
              />
            </div>
            <div>
              <label htmlFor="titulo" className="sr-only">Título da Manutenção</label>
              <input
                id="titulo"
                name="titulo"
                type="text"
                required
                value={formData.titulo}
                onChange={handleChange}
                className="appearance-none rounded-none relative block w-full px-3 py-2 border border-gray-300 placeholder-gray-500 text-gray-900 focus:outline-none focus:ring-primary-500 focus:border-primary-500 focus:z-10 sm:text-sm"
                placeholder="Título da Manutenção"
              />
            </div>
            <div>
              <label htmlFor="local" className="sr-only">Local</label>
              <input
                id="local"
                name="local"
                type="text"
                required
                value={formData.local}
                onChange={handleChange}
                className="appearance-none rounded-none relative block w-full px-3 py-2 border border-gray-300 placeholder-gray-500 text-gray-900 focus:outline-none focus:ring-primary-500 focus:border-primary-500 focus:z-10 sm:text-sm"
                placeholder="Local da Manutenção"
              />
            </div>
            <div>
              <label htmlFor="descricao" className="sr-only">Descrição</label>
              <textarea
                id="descricao"
                name="descricao"
                value={formData.descricao}
                onChange={handleChange}
                className="appearance-none rounded-none relative block w-full px-3 py-2 border border-gray-300 placeholder-gray-500 text-gray-900 rounded-b-md focus:outline-none focus:ring-primary-500 focus:border-primary-500 focus:z-10 sm:text-sm"
                placeholder="Descrição (opcional)"
                rows={4}
              />
            </div>
          </div>

          {mensagem && (
            <div className={`rounded-md p-4 ${
              mensagem.tipo === 'sucesso' ? 'bg-green-50 text-green-700' : 'bg-red-50 text-red-700'
            }`}>
              <p className="text-sm">{mensagem.texto}</p>
            </div>
          )}

          <div>
            <button
              type="submit"
              disabled={enviando}
              className={`group relative w-full flex justify-center py-2 px-4 border border-transparent text-sm font-medium rounded-md text-white bg-primary-600 hover:bg-primary-700 focus:outline-none focus:ring-2 focus:ring-offset-2 focus:ring-primary-500 ${
                enviando ? 'opacity-75 cursor-not-allowed' : ''
              }`}
            >
              {enviando ? 'Enviando...' : 'Enviar Solicitação'}
            </button>
          </div>
        </form>

        <div className="mt-6 text-center">
          <Link
            to="/admin/login"
            className="text-sm text-gray-600 hover:text-primary-500"
          >
            Entrar como administrador
          </Link>
        </div>
      </div>
    </div>
  );
}
